import { styleText } from 'node:util';
import { Flags } from '@oclif/core';
import { computeDiffEntries, errorMessage, workflow, } from '@sanity/workflow-engine';
import logSymbols from 'log-symbols';
import ora from 'ora';
import { WorkflowCommand } from "../../lib/base-command.js";
import { clientFor, resolveTokenOrFail } from "../../lib/client.js";
import { assertKnownDefinition, selectDefinitions, validateOrFail } from "../../lib/definitions.js";
import { diffReport } from "../../lib/diff.js";
import { fail, isAuthRejection } from "../../lib/fail.js";
import { deploymentFlags } from "../../lib/flags.js";
import { loadWorkflowConfig } from "../../lib/load-config.js";
import { acknowledgeDeployment, deploymentLabel, deploymentToTarget, selectDeployments, } from "../../lib/select-deployment.js";
import { shareDefinitionsAfterDeploy } from "../../lib/share-definitions.js";
import { cliTelemetry } from "../../lib/telemetry.js";
import { groupBanner, resourceLabel } from "../../lib/ui.js";
export default class Deploy extends WorkflowCommand {
    static description = 'Validate, diff, and deploy workflow definitions to the resource bound by the selected deployment.';
    static examples = [
        '<%= config.bin %> workflows deploy --deployment review-prod',
        '<%= config.bin %> workflows deploy --tag prod',
        '<%= config.bin %> workflows deploy --all-tags',
        '<%= config.bin %> workflows deploy --check',
        '<%= config.bin %> workflows deploy --dry-run',
        '<%= config.bin %> workflows deploy --only productLaunch',
    ];
    static flags = {
        ...deploymentFlags,
        tag: Flags.string({
            description: 'Workflow environment tag (e.g. prod, test) — deploys every deployment carrying the tag (a tag is an environment group).',
            exclusive: ['deployment'],
        }),
        'all-tags': Flags.boolean({
            description: 'Deploy every deployment in the config, not just a selection.',
            default: false,
            exclusive: ['tag', 'deployment'],
        }),
        'dry-run': Flags.boolean({
            description: 'Validate + diff against the deployed version; do not write.',
            default: false,
        }),
        check: Flags.boolean({
            description: 'Validate definitions only; do not contact the dataset.',
            default: false,
        }),
        only: Flags.string({
            description: 'Limit deploy/check/diff to a single workflow definition by name (deployments are selected with --deployment). Every targeted deployment must contain it.',
        }),
        'share-defs': Flags.boolean({
            allowNo: true,
            description: 'Share the definition documents newly created by this deploy with Sanity — the full document, verbatim (structure, names, filters, effect configuration, seeded values), plus its deployment coordinates (project and dataset, or resource id); never content documents, instances, or your Sanity auth token. Sharing is the default in every environment, including CI / non-TTY / DO_NOT_TRACK. Use --no-share-defs to opt out.',
        }),
    };
    async run() {
        const { flags } = await this.parse(Deploy);
        validateModeFlags(flags.check, flags['dry-run']);
        const config = await loadWorkflowConfig();
        const batches = await resolveBatches(config, {
            only: flags.only,
            selection: { name: flags.deployment, tag: flags.tag, allTags: flags['all-tags'] },
        });
        const log = (line) => this.log(line);
        if (flags.check) {
            await reconcileBatches({
                batches,
                log,
                processBatch: async ({ defs }) => {
                    log(`${logSymbols.success} ${defs.length} definition(s) passed validation (check only — dataset not contacted).`);
                },
            });
            return;
        }
        const token = await resolveTokenOrFail();
        const candidates = [];
        const failures = await reconcileBatches({
            batches,
            log,
            processBatch: async ({ deployment, defs }) => {
                const client = clientFor(deployment.workflowResource, token);
                const deployed = await this.processDeployment({
                    deployment,
                    defs,
                    dryRun: flags['dry-run'],
                    client,
                });
                if (deployed !== undefined) {
                    candidates.push({
                        client,
                        tag: deployment.tag,
                        resource: deployment.workflowResource,
                        results: deployed.results,
                        deployId: deployed.deployId,
                    });
                }
            },
        });
        for (const line of deploySummary({ total: batches.length, failures })) {
            log(line);
        }
        await shareDefinitionsAfterDeploy({
            flag: flags['share-defs'],
            candidates,
            warn: (message) => this.warn(message),
        });
        if (failures.length > 0) {
            this.exit(1);
        }
    }
    async processDeployment({ deployment, defs, dryRun, client, }) {
        const target = deploymentToTarget(deployment);
        const where = targetLabel(deployment);
        const resource = resourceLabel(deployment.workflowResource);
        if (dryRun) {
            await this.runDryRun({ client, defs, target, where, resource });
            return undefined;
        }
        return this.executeDeploy({ client, defs, target, where });
    }
    async executeDeploy({ client, defs, target, where, }) {
        const spinner = ora(deployStartLine(defs.length, where)).start();
        try {
            const deployed = await workflow.deployDefinitions({
                ...target,
                client,
                definitions: defs,
                telemetry: cliTelemetry().logger,
            });
            spinner.succeed(resultLine({ verb: 'Processed', count: deployed.results.length, where }));
            for (const line of deployResultLines(deployed.results))
                this.log(line);
            return deployed;
        }
        catch (error) {
            spinner.fail(`Deploy failed — ${errorMessage(error)}`);
            throw error;
        }
    }
    async runDryRun({ client, defs, target, where, resource, }) {
        const spinner = ora(dryRunStartLine(defs.length, resource)).start();
        try {
            const entries = await computeDiffEntries({ client, defs, target });
            spinner.succeed(resultLine({ verb: 'Diffed', count: defs.length, where }));
            for (const line of diffReport(entries))
                this.log(line);
        }
        catch (error) {
            spinner.fail(`Diff failed — ${errorMessage(error)}`);
            throw error;
        }
    }
}
export function validateModeFlags(check, dryRun) {
    if (check && dryRun) {
        fail('Pass either --check or --dry-run, not both.');
    }
}
export async function resolveBatches(config, { only, selection }) {
    assertKnownDefinition(config, only);
    return buildBatches(await selectDeployments(config, selection), only);
}
export function buildBatches(deployments, only) {
    return deployments.map((deployment) => {
        const context = deployments.length > 1 ? `${deploymentLabel(deployment)} — ` : '';
        const defs = selectDefinitions(deployment.definitions, { only, context });
        validateOrFail(defs, context);
        return { deployment: acknowledgeDeployment(deployment, defs), defs };
    });
}
export async function reconcileBatches({ batches, log, processBatch, }) {
    const failures = [];
    for (const [index, batch] of batches.entries()) {
        const banner = deploymentBanner({ deployment: batch.deployment, index, total: batches.length });
        if (banner !== undefined) {
            log(banner);
        }
        try {
            await processBatch(batch);
        }
        catch (error) {
            if (batches.length === 1 || isAuthRejection(error)) {
                throw error;
            }
            failures.push({ deployment: batch.deployment, message: errorMessage(error) });
        }
    }
    return failures;
}
export function deploySummary({ total, failures, }) {
    if (failures.length === 0) {
        return [];
    }
    return [
        '',
        styleText('bold', `${total - failures.length} of ${total} deployments succeeded — ${failures.length} failed:`),
        ...failures.flatMap((f) => {
            const [first = '', ...rest] = f.message.split('\n');
            return [
                styleText('red', `  ${logSymbols.error} ${deploymentLabel(f.deployment)} — ${first}`),
                ...rest.map((line) => styleText('red', `    ${line}`)),
            ];
        }),
    ];
}
export function deploymentBanner({ deployment, index, total, }) {
    return groupBanner({ label: deploymentLabel(deployment), index, total });
}
export function targetLabel(deployment) {
    return `${deploymentLabel(deployment)} → ${resourceLabel(deployment.workflowResource)}`;
}
export function deployStartLine(count, where) {
    return `Deploying ${count} definition(s) to ${where}…`;
}
export function dryRunStartLine(count, resource) {
    return `Diffing ${count} definition(s) against ${resource}…`;
}
export function resultLine({ verb, count, where, }) {
    return `${verb} ${count} definition(s) · ${where}`;
}
export function deployResultLines(results) {
    const symbols = {
        created: logSymbols.success,
    };
    return results.flatMap((r) => {
        const symbol = symbols[r.status] ?? logSymbols.warning;
        const head = `  ${symbol} ${r.status.padEnd(9)} ${r.name} v${r.version}`;
        const warnings = (r.warnings ?? []).map((w) => `      ${logSymbols.warning} ${w}`);
        return [head, ...warnings];
    });
}
